#include "coagentics/experiment/MarketScientist.hpp"
#include <cassert>
#include <cmath>
using namespace coagentics::experiment;
int main(){Probe news{"news",8,0,1};CdaMarketDomain responsive("signal-responsive",1500),blind("information-blind",1500);auto a=responsive.run_market(news,101),b=responsive.run_market(news,101);assert(a.control.efficiency==b.control.efficiency);assert(a.treatment.mean_target_quote==b.treatment.mean_target_quote);assert(a.control.trades>0);assert(a.control.efficiency>=0&&a.control.efficiency<=100);assert(a.treatment.efficiency>=0&&a.treatment.efficiency<=100);auto z=blind.run_market(news,101);assert(z.control.mean_target_quote==z.treatment.mean_target_quote);assert(z.control.efficiency==z.treatment.efficiency);bool observed=false;for(int i=0;i<20;++i){auto x=responsive.run_market(news,100+i);if(std::abs(x.treatment.mean_target_quote-x.control.mean_target_quote)>1e-5)observed=true;}assert(observed);std::vector<Candidate>c={{"blind",0,0,0,.333},{"news",1,0,0,.334},{"peer",0,.6,0,.333}};std::vector<Probe>p={{"news-only",8,0,1},{"peer-only",0,8,1}};ScientistConfig cfg;cfg.replicates=4;cfg.max_experiments=2;cfg.noise_sd=2.;cfg.minimum_separation=.1;auto r=run_market_scientist(responsive,c,p,42,cfg);assert(!r.scientist.steps.empty());assert(r.selected_probe_market_pairs.size()==r.scientist.steps.size());}
